create or replace function switch_dbuser() RETURNS void as $$
declare
    name text;
begin
	select into name 10::regrole;
    execute format('set role %s;', name);
	return;
end; $$ language plpgsql;
/

set ivorysql.compatible_mode to pg;
select switch_dbuser();

create database nlssort_gbk encoding='GBK' LC_COLLATE='C' LC_CTYPE='C' TEMPLATE=template0;
\c nlssort_gbk;
load 'gb18030_2022';

set ivorysql.compatible_mode to oracle;
set role system;

SET client_encoding=GBK;

CREATE TABLE nlssort_gbk(id serial, val varchar(8));

