-- nlssort
select id, val, nlssort(val, 'nls_sort=binary')             from nlssort_gbk order by nlssort(val, 'nls_sort=binary'), id;
select id, val, nlssort(val, 'nls_sort=generic_m_ci')       from nlssort_gbk order by nlssort(val, 'nls_sort=generic_m_ci'), id;
select id, val, nlssort(val, 'nls_sort=schinese_pinyin_m')  from nlssort_gbk order by nlssort(val, 'nls_sort=schinese_pinyin_m'), id;
select id, val, nlssort(val, 'nls_sort=schinese_stroke_m')  from nlssort_gbk order by nlssort(val, 'nls_sort=schinese_stroke_m'), id;
select id, val, nlssort(val, 'nls_sort=schinese_radical_m') from nlssort_gbk order by nlssort(val, 'nls_sort=schinese_radical_m'), id;
select id, val, nlssort(val, 'nls_sort=uca0700_schinese')   from nlssort_gbk order by nlssort(val, 'nls_sort=uca0700_schinese'), id;
select id, val, nlssort(val, 'nls_sort=uca0700_schinese1')  from nlssort_gbk order by nlssort(val, 'nls_sort=uca0700_schinese1'), id;
select id, val, nlssort(val, 'nls_sort=uca0700_schinese2')  from nlssort_gbk order by nlssort(val, 'nls_sort=uca0700_schinese2'), id;

-- collate
select id, val, nlssort(val, 'nls_sort=binary')             from nlssort_gbk order by val collate binary, id;
select id, val, nlssort(val, 'nls_sort=generic_m_ci')       from nlssort_gbk order by val collate generic_m_ci, id;
select id, val, nlssort(val, 'nls_sort=schinese_pinyin_m')  from nlssort_gbk order by val collate schinese_pinyin_m, id;
select id, val, nlssort(val, 'nls_sort=schinese_stroke_m')  from nlssort_gbk order by val collate schinese_stroke_m, id;
select id, val, nlssort(val, 'nls_sort=schinese_radical_m') from nlssort_gbk order by val collate schinese_radical_m, id;
select id, val, nlssort(val, 'nls_sort=uca0700_schinese')   from nlssort_gbk order by val collate uca0700_schinese, id;
select id, val, nlssort(val, 'nls_sort=uca0700_schinese1')  from nlssort_gbk order by val collate uca0700_schinese1, id;
select id, val, nlssort(val, 'nls_sort=uca0700_schinese2')  from nlssort_gbk order by val collate uca0700_schinese2, id;
